import type { FAILURE, Unlisted } from '@cancjs/promise';
export type CoFailureOf<T> = 0 extends 1 & T ? never : T extends {
    readonly [FAILURE]?: infer F;
} ? [
    F
] extends [undefined] ? never : Exclude<F, Unlisted> : never;
export type CoBodyFailureOf<TYield> = 0 extends 1 & TYield ? never : unknown extends TYield ? unknown : CoFailureOf<TYield>;
